import{_ as o,o as a,c as d,a5 as r}from"./chunks/framework.BZzouRtU.js";const i="/study/images/browser/audio-mixing-graph.svg",t="/study/images/browser/audio-clipping-waveform.svg",p=JSON.parse('{"title":"Web Audioのミキシング — ゲイン・ヘッドルーム・クリッピング","description":"","frontmatter":{"title":"Web Audioのミキシング — ゲイン・ヘッドルーム・クリッピング","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"同じ時点の音声サンプルを加算し、ゲインを掛ける順序と、クリッピングで波形が変わる仕組みを図解する。","aliases":["Web Audio API","audio mixing","ミキシング","GainNode","ゲイン","マスターゲイン","WaveShaperNode","ヘッドルーム","クリッピング","hard clip","dBFS","ピーク"],"verification":"W3C Web Audio APIのノード入力のミックス・GainNode・WaveShaperNode・AudioBufferに照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-mixing-and-headroom.md","filePath":"browser/audio-mixing-and-headroom.md"}'),n={name:"browser/audio-mixing-and-headroom.md"};function c(s,e,u,g,l,h){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="web-audioのミキシング-—-ゲイン・ヘッドルーム・クリッピング" tabindex="-1">Web Audioのミキシング — ゲイン・ヘッドルーム・クリッピング <a class="header-anchor" href="#web-audioのミキシング-—-ゲイン・ヘッドルーム・クリッピング" aria-label="Permalink to &quot;Web Audioのミキシング — ゲイン・ヘッドルーム・クリッピング&quot;">​</a></h1><p>ゲームでは、効果音や音楽が同時に鳴ります。複数の音を一つの出力へ流すと、同じ時点のサンプルが足し合わされます。それぞれの音の振幅に余裕があっても、足した結果のピークは出力先で扱える範囲を超えることがあります。<a href="https://www.w3.org/TR/webaudio-1.1/#channel-up-mixing-and-down-mixing" target="_blank" rel="noreferrer">W3C Web Audio APIのチャンネルのミックス</a></p><h2 id="ゲインを掛けてから、同じ時点の値を足す" tabindex="-1">ゲインを掛けてから、同じ時点の値を足す <a class="header-anchor" href="#ゲインを掛けてから、同じ時点の値を足す" aria-label="Permalink to &quot;ゲインを掛けてから、同じ時点の値を足す&quot;">​</a></h2><p><strong>ゲイン</strong>はサンプルの振幅に掛ける倍率です。たとえばゲインを <code>0.5</code> にすると、正のサンプルも負のサンプルも、絶対値が半分になります。Web Audioでは <code>GainNode</code> が各入力サンプルに <code>gain</code> を掛けます。複数の信号を同じ入力につなぐと、その入力で対応するチャンネルの値が足されます。<a href="https://www.w3.org/TR/webaudio-1.1/#GainNode" target="_blank" rel="noreferrer">W3C Web Audio APIのGainNode</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#channel-up-mixing-and-down-mixing" target="_blank" rel="noreferrer">チャンネルのミックス</a></p><p>実践では、二つのモノラル音源をそれぞれの <code>GainNode</code> に通し、まとめてマスターの <code>GainNode</code> に接続します。フレーム <code>n</code> の音源を <code>A[n]</code> と <code>B[n]</code> とすると、マスターの出力は <code>(A[n] × gA + B[n] × gB) × gM</code> です。 <code>gA</code> と <code>gB</code> で各音源のバランスを変え、 <code>gM</code> で足し合わせた音全体の大きさを調整できます。</p><figure class="study-figure"><img src="'+i+'" alt="二つのモノラル音源の値に個別ゲインを掛け、同じ入力で足し合わせる。マスターゲインを掛けた信号は、直接とWaveShaperNodeを経由する二つの経路に分かれ、結果はAudioBufferのチャンネル0と1に入る。" width="760" height="1040" loading="lazy"><figcaption>同じ入力で音源を足し、マスターの出力を二つの経路に分けます。<a href="/study/images/browser/audio-mixing-graph.svg" target="_blank" rel="noopener noreferrer">ミキシングの信号経路を拡大</a></figcaption></figure><h2 id="合計のピークからヘッドルームを読む" tabindex="-1">合計のピークからヘッドルームを読む <a class="header-anchor" href="#合計のピークからヘッドルームを読む" aria-label="Permalink to &quot;合計のピークからヘッドルームを読む&quot;">​</a></h2><p>実践の音源は両方とも400 Hzの正弦波で、ピークは <code>0.65</code> です。同じ位相で同時に鳴るので、正の山と負の谷がそれぞれ重なります。すべてのゲインを <code>1</code> にすると、合計は <code>+1.30</code> まで上がり、 <code>−1.30</code> まで下がります。音源の位相や波形が変われば、同じ時点で足される値も変わります。たとえば同じ正弦波でも、一方の符号を逆にすると打ち消し合います。</p><p><strong>ピーク</strong>は、調べる範囲で各サンプルの絶対値を比べたときの最大値です。この実践では振幅 <code>1</code> をフルスケールの基準とし、ピークの dBFS を <code>20 × log10(ピーク ÷ 1)</code> で求めます。 <code>1</code> が <code>0 dBFS</code>、 <code>0.65</code> が約 <code>−3.74 dBFS</code>、浮動小数点の合計 <code>1.30</code> はこの基準で約 <code>+2.28 dBFS</code> です。ピークが <code>0.65</code> のとき、基準まで約 <code>3.74 dB</code> の<strong>ヘッドルーム</strong>があります。これは一瞬の振幅の余裕を表します。聴こえる音量を比較するときは、音の長さや周波数も関わります。</p><h2 id="クリップする前にゲインを下げる" tabindex="-1">クリップする前にゲインを下げる <a class="header-anchor" href="#クリップする前にゲインを下げる" aria-label="Permalink to &quot;クリップする前にゲインを下げる&quot;">​</a></h2><p><strong>ハードクリッピング</strong>では、しきい値を超えたサンプルをその境界の値にそろえます。実践では、マスターの出力を <code>WaveShaperNode</code> に送り、 <code>curve</code> を <code>[-1, 1]</code> に設定します。 <code>−1</code> から <code>1</code> までは直線で補間されて入力と同じ値が出ます。入力がこの範囲を超えると、出力は近い側の端点になります。<a href="https://www.w3.org/TR/webaudio-1.1/#dom-waveshapernode-curve" target="_blank" rel="noreferrer">W3C Web Audio APIのWaveShaperNode</a></p><p>ピーク <code>1.30</code> の波形にクリッピングを掛けると、山と谷の先が平らになります。正弦波にこの処理を掛けると、元の周波数の整数倍にあたる成分が加わり、音色が変わります。クリップの手前でマスターゲインを <code>0.5</code> にすると、ピークは <code>0.65</code> まで下がり、波形の形が保たれます。クリップの後で <code>0.5</code> 倍にした場合は、平らになった部分も一緒に小さくなります。</p><figure class="study-figure"><img src="'+t+'" alt="同じ400ヘルツの波形を共通の振幅目盛で比較する。上段の合計波形はピークが1.30で正負の境界を超える。中段は境界で山と谷が平らになる。下段はクリップ前のマスターゲインを0.5にした波形で、ピーク0.65の正弦波になる。" width="760" height="1130" loading="lazy"><figcaption>横軸は400 Hzの正弦波2周期分の5 msです。縦軸は全段で共通です。<a href="/study/images/browser/audio-clipping-waveform.svg" target="_blank" rel="noopener noreferrer">クリッピング前後の波形を拡大</a></figcaption></figure><h2 id="二つの経路を同時にレンダリングする" tabindex="-1">二つの経路を同時にレンダリングする <a class="header-anchor" href="#二つの経路を同時にレンダリングする" aria-label="Permalink to &quot;二つの経路を同時にレンダリングする&quot;">​</a></h2><p>実践の <code>OfflineAudioContext</code> は、マスターの出力を二つの経路に分けて一度に計算します。直接つないだ信号を <code>ChannelMergerNode</code> の入力0、 <code>WaveShaperNode</code> を通した信号を入力1に入れます。レンダリング結果のチャンネル0と1を読むと、同じフレームでクリップする前と後を比べられます。<a href="https://www.w3.org/TR/webaudio-1.1/#ChannelMergerNode" target="_blank" rel="noreferrer">W3C Web Audio APIのChannelMergerNode</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#OfflineAudioContext" target="_blank" rel="noreferrer">OfflineAudioContext</a></p><p><code>AudioBuffer</code> は浮動小数点PCMを保持し、振幅の基準範囲を超える値も格納できます。この実践で観察するクリッピングは、グラフに置いた <code>WaveShaperNode</code> の処理です。実際の再生経路や整数PCMへの変換でどこまで表せるかは、使う出力先や形式の仕様で決まります。<a href="https://www.w3.org/TR/webaudio-1.1/#AudioBuffer" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioBuffer</a></p><p>個別ゲインとマスターゲインを操作して、しきい値を超えたフレーム数や波形を比べられます。連続して出力する音声データを用意する仕組みは、前回の記事で扱います。<a href="/study/practice/browser/audio-mixing-observation.html">ミキシングとクリッピングの実践</a>、<a href="/study/browser/audio-worklet-buffering.html">AudioWorkletと音声バッファ</a></p><p>再生中にゲインを変えるときは、値に加えて、いつどのくらいの速さで変えるかも波形に影響します。<a href="/study/browser/audio-gain-automation.html">Web Audioのゲインオートメーション</a>で、急な消音とフェードの違いを確認できます。</p>',18)])])}const w=o(n,[["render",c]]);export{p as __pageData,w as default};
